#!/usr/bin/env bash
# prune-ci-cache.sh — keep ~/.ci-cache from eating the root filesystem.
#
# Why this exists: the debug build cache has reached 56-71 GB four times
# (2026-10-19 it filled the disk and halted the chain; 2026-11-06/07 twice
# more). Every time it was noticed by hand. This runs unattended instead.
#
# Policy, deliberately conservative:
#   * NEVER prune while a build is running (cargo/rustc/ld present).
#   * Prune only the DEBUG profile: it is regenerated by the next `cargo test`,
#     and no release artifact depends on it. The release cache is what makes CI
#     fast, and is left alone.
#   * Skip a directory touched in the last MIN_AGE_HOURS (default 12): a fresh
#     debug build may still be the base for the current one.
#   * Also drop `incremental` and the tmpdir, which are pure scratch.
#
# Exit 0 = nothing to do or pruned; the script never fails a caller.
set -uo pipefail

MIN_AGE_HOURS="${MIN_AGE_HOURS:-12}"
FREE_FLOOR_PCT="${FREE_FLOOR_PCT:-15}"   # prune when free space is below this
cache="${GPN_CI_CACHE:-$HOME/.ci-cache}"

[ -d "$cache" ] || exit 0

say() { echo "[prune-ci-cache] $*"; }

# Never touch a tree that is being written.
if pgrep -x cargo >/dev/null 2>&1 || pgrep -x rustc >/dev/null 2>&1; then
  say "a build is running — skipping"
  exit 0
fi

free_pct=$(df --output=pcent "$cache" 2>/dev/null | tail -1 | tr -dc '0-9')
free_pct=${free_pct:-0}
used_pct=$((100 - free_pct))

if [ "$used_pct" -lt "$FREE_FLOOR_PCT" ]; then
  say "disk at ${used_pct}% used (below ${FREE_FLOOR_PCT}% floor) — nothing to reclaim"
  exit 0
fi

say "disk at ${used_pct}% used — pruning debug caches older than ${MIN_AGE_HOURS}h"

freed_kb=0
while IFS= read -r -d '' dir; do
  # Skip anything touched recently: it may be the base layer of an active build.
  if [ -n "$(find "$dir" -maxdepth 0 -mmin -$((MIN_AGE_HOURS * 60)) 2>/dev/null)" ]; then
    say "keeping $dir (touched recently)"
    continue
  fi
  kb=$(du -sk "$dir" 2>/dev/null | cut -f1); kb=${kb:-0}
  if rm -rf "$dir" 2>/dev/null; then
    freed_kb=$((freed_kb + kb))
    say "removed $dir ($((kb / 1024)) MiB)"
  else
    say "could not remove $dir"
  fi
done < <(find "$cache" -maxdepth 3 -type d \( -name debug -o -name incremental \) -print0 2>/dev/null)

say "reclaimed $((freed_kb / 1024)) MiB; now $(df --output=pcent "$cache" | tail -1 | tr -d ' ') used"
exit 0
